mapper.select:
SELECT 
  FROM docs_download_runtime
 WHERE saved_file_name = #{fileName}
    OR original_file_name = #{fileName}
 ORDER BY updated_at DESC
 LIMIT 1

SELECT 
  FROM docs_download_runtime
 WHERE created_at < #{startupCutoff}
   AND (
        audit_saved = FALSE
        OR expire_at <= #{startupCutoff}
   )
 ORDER BY created_at, ws_seq

mapper.update:
UPDATE docs_download_runtime
   SET status_cd = 'FAILED',
       result_code = COALESCE(NULLIF(result_code, ''), '99'),
       optional_data = NULL,
       error_message = #{errorMessage},
       updated_at = CURRENT_TIMESTAMP,
       expire_at = LEAST(expire_at, CURRENT_TIMESTAMP)
 WHERE ws_seq = #{wsSeq}
   AND created_at < #{startupCutoff}
   AND (
        status_cd NOT IN ('COMPLETED', 'FAILED')
        OR expire_at <= #{startupCutoff}
   )
